  (id, label, brand, code, finish_type_label, pattern_category, solid_color, albedo_url, procedural_kind, normal_map_url, roughness_map_url, relief_strength, roughness, clearcoat, clearcoat_roughness, metalness, swatch_width_mm, swatch_height_mm, tiling_mode, price_per_sq_m, source, created_at, updated_at)
